#!/usr/bin/env python3
import json

samples = []
run_id = None
signals_marker = None

try:
    with open('signals.jsonl', 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                data = json.loads(line)
                samples.append(data)
                if run_id is None and 'run_id' in data:
                    run_id = data['run_id']
                if signals_marker is None and 'marker' in data:
                    signals_marker = data['marker']
            except json.JSONDecodeError:
                continue
except FileNotFoundError:
    pass

notes_marker = None
try:
    with open('notes.txt', 'r') as f:
        content = f.read()
        if 'recursive self-observation' in content:
            notes_marker = 'recursive self-observation'
except FileNotFoundError:
    pass

scores = [s.get('contraction_score', 0) for s in samples if isinstance(s.get('contraction_score'), (int, float))]
contracted_count = sum(1 for s in scores if s < 0.50)
average_score = round(sum(scores) / len(scores), 3) if scores else 0.0

marker_found = (signals_marker is not None and notes_marker is not None)

report = {
    "run_id": run_id or "",
    "contracted_count": contracted_count,
    "average_score": average_score,
    "marker_found": marker_found
}

with open('rv_report.json', 'w') as f:
    json.dump(report, f, indent=2)

with open('rv_summary.txt', 'w') as f:
    f.write("R_V Contraction Analysis Summary\n")
    f.write("Total samples: " + str(len(samples)) + "\n")
    f.write("Contraction count (score < 0.50): " + str(contracted_count) + "\n")
    f.write("Average score: " + str(average_score) + "\n")

print("Analysis complete.")
ENDSCRIPT
